import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { MATCH_MIN_WORDS, buildMatchBoard, seededRng, type MatchBoard } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ModeScreen, ModeSummary, NoTimer } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { saveModePrefs } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import { formatClock, useClock } from '../useClock.js';
import styles from '../Modes.module.css';

type Side = 'word' | 'meaning';

/** How long a wrong pair stays marked before the board settles again. */
const WRONG_SHOWN_MS = 450;

/**
 * Match: six of the learner's words and their meanings, in two shuffled
 * columns. Tap one, then its partner, from either side. A wrong pair shakes
 * (an outline only, with reduced motion) and is counted against the word
 * asked first; a right pair is crossed off.
 *
 * Practice only (card type match, source game): each pair is logged once,
 * right when it was matched with no wrong try, and never moves a box.
 */
export function Match({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('match');
  const board = useMemo<MatchBoard | undefined>(
    () => buildMatchBoard(view.words, view.today, seededRng(run.seed)),
    // A new board per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [run.seed],
  );
  const [picked, setPicked] = useState<{ side: Side; id: string } | undefined>(undefined);
  const [done, setDone] = useState<ReadonlySet<string>>(new Set());
  const [wrong, setWrong] = useState<{ word: string; meaning: string } | undefined>(undefined);
  const [said, setSaid] = useState('');
  // The first wrong partner of each tile asked first, for the log and the confusion pair.
  const [missed, setMissed] = useState<ReadonlyMap<string, string>>(new Map());
  const [misses, setMisses] = useState(0);
  const lastMatch = useRef(0);
  const noTimer = view.prefs.noTimer;
  const finished = board?.pairs.length === done.size;
  const seconds = useClock(!finished, run.seed);

  useEffect(() => {
    lastMatch.current = Date.now();
  }, [run.seed]);
  const tiles = useRef(new Map<string, HTMLButtonElement>());

  const pairOf = useCallback((id: string) => board?.pairs.find((pair) => pair.id === id), [board]);

  useEffect(() => {
    if (wrong === undefined) return undefined;
    const id = window.setTimeout(() => {
      setWrong(undefined);
    }, WRONG_SHOWN_MS);
    return () => {
      window.clearTimeout(id);
    };
  }, [wrong]);

  const tap = useCallback(
    (side: Side, id: string): void => {
      if (done.has(id) || wrong !== undefined) return;
      if (picked === undefined || picked.side === side) {
        setPicked({ side, id });
        const pair = pairOf(id);
        if (pair !== undefined && side === 'word') setSaid(t('modes.matchPicked', { word: pair.headword }));
        return;
      }
      const asked = picked.id;
      const word = side === 'word' ? id : picked.id;
      const meaning = side === 'meaning' ? id : picked.id;
      setPicked(undefined);
      const pair = pairOf(asked);
      if (pair === undefined) return;
      if (word === meaning) {
        setDone((current) => new Set([...current, word]));
        setSaid(t('modes.matchRight', { word: pair.headword }));
        const firstWrong = missed.get(word);
        const now = Date.now();
        void run.record({
          wordId: word,
          headword: pair.headword,
          correct: firstWrong === undefined,
          latencyMs: now - lastMatch.current,
          ...(firstWrong === undefined ? {} : { pickedWordId: firstWrong }),
        });
        lastMatch.current = now;
        return;
      }
      // `asked` is the tile tapped first; the second is what it was taken for.
      const takenFor = side === 'word' ? word : meaning;
      if (!missed.has(asked)) setMissed(new Map([...missed, [asked, takenFor]]));
      setMisses((count) => count + 1);
      setWrong({ word, meaning });
      setSaid(t('modes.matchWrong'));
    },
    [done, wrong, picked, pairOf, missed, run],
  );

  if (board === undefined) {
    // The route checked the notebook can feed a board; words retired since
    // then can still leave too few. Nothing to draw but the way back.
    return (
      <ModeSummary
        title={t('modes.match')}
        lang={lang}
        score={t('modes.fewMatch', { count: MATCH_MIN_WORDS })}
        missed={[]}
        onAgain={run.restart}
      />
    );
  }

  const again = (): void => {
    run.restart();
    setMissed(new Map());
    setMisses(0);
    setDone(new Set());
    setPicked(undefined);
    setWrong(undefined);
    setSaid('');
  };

  if (finished) {
    return (
      <ModeSummary
        title={t('modes.match')}
        lang={lang}
        score={
          noTimer
            ? t('modes.scoreOf', { right: board.pairs.length - missed.size, total: board.pairs.length })
            : t('modes.matchTime', { time: formatClock(seconds) })
        }
        lines={[misses === 0 ? t('modes.matchNoMisses') : t('modes.matchMisses', { count: misses })]}
        missed={missedWords(run.answers)}
        onAgain={again}
      />
    );
  }

  // Arrow keys move between tiles: up and down in a column, left and right
  // across to the same row of the other one. Enter or Space taps.
  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>): void => {
    const target = event.target as HTMLElement;
    const side = target.dataset.side as Side | undefined;
    const index = Number(target.dataset.index);
    if (side === undefined || Number.isNaN(index)) return;
    const size = board.pairs.length;
    let next: { side: Side; index: number } | undefined;
    if (event.key === 'ArrowDown') next = { side, index: Math.min(size - 1, index + 1) };
    if (event.key === 'ArrowUp') next = { side, index: Math.max(0, index - 1) };
    if (event.key === 'ArrowLeft') next = { side: 'word', index };
    if (event.key === 'ArrowRight') next = { side: 'meaning', index };
    if (next === undefined) return;
    event.preventDefault();
    tiles.current.get(`${next.side}-${String(next.index)}`)?.focus();
  };

  const column = (side: Side, ids: readonly string[]): React.JSX.Element => (
    <div
      className={styles.column}
      role="group"
      aria-label={side === 'word' ? t('modes.matchWords') : t('modes.matchMeanings')}
    >
      <h2 className={styles.columnTitle} aria-hidden="true">
        {side === 'word' ? t('modes.matchWords') : t('modes.matchMeanings')}
      </h2>
      <div className={styles.columnGrid}>
        {ids.map((id, index) => {
          const pair = pairOf(id);
          if (pair === undefined) return null;
          const isDone = done.has(id);
          const isPicked = picked?.side === side && picked.id === id;
          const isWrong = wrong !== undefined && (side === 'word' ? wrong.word : wrong.meaning) === id;
          return (
            <button
              key={id}
              ref={(element) => {
                if (element === null) tiles.current.delete(`${side}-${String(index)}`);
                else tiles.current.set(`${side}-${String(index)}`, element);
              }}
              type="button"
              data-side={side}
              data-index={index}
              className={cx(
                styles.tile,
                isPicked && styles.tilePicked,
                isDone && styles.tileDone,
                isWrong && styles.wrong,
                isWrong && styles.shake,
              )}
              data-state={isWrong ? 'wrong' : isDone ? 'done' : isPicked ? 'picked' : undefined}
              aria-pressed={isPicked}
              aria-disabled={isDone}
              aria-label={
                isDone
                  ? `${side === 'word' ? pair.headword : pair.meaning}, ${t('modes.matched')}`
                  : undefined
              }
              onClick={() => {
                tap(side, id);
              }}
            >
              <Bilingual lang={side === 'word' ? lang : meaningLang}>
                {side === 'word' ? pair.headword : pair.meaning}
              </Bilingual>
            </button>
          );
        })}
      </div>
    </div>
  );

  return (
    <ModeScreen
      title={t('modes.match')}
      ask={t('modes.matchAsk')}
      counts={false}
      progress={{ done: done.size, total: board.pairs.length }}
      timer={noTimer ? undefined : { seconds, label: t('modes.timeTaken', { count: seconds }) }}
      said={said}
      actions={
        <NoTimer
          on={noTimer}
          onChange={(on) => {
            void saveModePrefs((prefs) => ({ ...prefs, noTimer: on }));
          }}
        />
      }
    >
      <div className={styles.board} onKeyDown={onKeyDown}>
        {column('word', board.words)}
        {column('meaning', board.meanings)}
      </div>
    </ModeScreen>
  );
}
